CREATE TRIGGER dbo.updEmployeeData ON dbo.employeeData AFTER UPDATE AS /*Check whether columns 2, 3 or 4 have been updated. If any or all columns 2, 3 or 4 have been changed, create an audit record. The bitmask is: power(2,(2-1))+power(2,(3-1))+power(2,(4-1)) = 14. To test whether all columns 2, 3, and 4 are updated, use = 14 instead of >0 (below).*/
IF (COLUMNS_UPDATED() & 14) > 0 /*Use IF (COLUMNS_UPDATED() & 14) = 14 to see whether all columns 2, 3, and 4 are updated.*/ BEGIN -- Audit OLD record. INSERT INTO dbo.auditEmployeeData (audit_log_type, audit_emp_id, audit_emp_bankAccountNumber, audit_emp_salary, audit_emp_SSN) SELECT 'OLD', del.emp_id, del.emp_bankAccountNumber, del.emp_salary, del.emp_SSN FROM deleted del;
-- Audit NEW record. INSERT INTO dbo.auditEmployeeData (audit_log_type, audit_emp_id, audit_emp_bankAccountNumber, audit_emp_salary, audit_emp_SSN) SELECT 'NEW', ins.emp_id, ins.emp_bankAccountNumber, ins.emp_salary, ins.emp_SSN FROM inserted ins; END; GO

CREATE TRIGGER reminder2
ON Sales.Customer
AFTER INSERT, UPDATE, DELETE 
AS
   EXEC msdb.dbo.sp_send_dbmail
        @profile_name = 'AdventureWorks2012 Administrator',
        @recipients = 'danw@Adventure-Works.com',
        @body = 'Don''t forget to print a report for the sales force.',
        @subject = 'Reminder';
GO


      CREATE TRIGGER [Person].[iuPerson] ON [Person].[Person] 
      AFTER INSERT, UPDATE NOT FOR REPLICATION AS 
      BEGIN
	      DECLARE @Count int;

	      SET @Count = @@ROWCOUNT;
	      IF @Count = 0 
		      RETURN;

	      SET NOCOUNT ON;

	      IF UPDATE([BusinessEntityID]) OR UPDATE([Demographics]) 
	      BEGIN
		      UPDATE [Person].[Person] 
		      SET [Person].[Person].[Demographics] = N'<IndividualSurvey xmlns="http://schemas.microsoft.com/sqlserver/2004/07/adventure-works/IndividualSurvey"> 
			      <TotalPurchaseYTD>0.00</TotalPurchaseYTD> 
			      </IndividualSurvey>' 
		      FROM inserted 
		      WHERE [Person].[Person].[BusinessEntityID] = inserted.[BusinessEntityID] 
			      AND inserted.[Demographics] IS NULL;

		      UPDATE [Person].[Person] 
		      SET [Demographics].modify(N'declare default element namespace "http://schemas.microsoft.com/sqlserver/2004/07/adventure-works/IndividualSurvey"; 
			      insert <TotalPurchaseYTD>0.00</TotalPurchaseYTD> 
			      as first 
			      into (/IndividualSurvey)[1]') 
		      FROM inserted 
		      WHERE [Person].[Person].[BusinessEntityID] = inserted.[BusinessEntityID] 
			      AND inserted.[Demographics] IS NOT NULL 
			      AND inserted.[Demographics].exist(N'declare default element namespace 
				      "http://schemas.microsoft.com/sqlserver/2004/07/adventure-works/IndividualSurvey"; 
				      /IndividualSurvey/TotalPurchaseYTD') <> 1;
	      END;
      END;
